"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66854"],{68417(e){e.exports=JSON.parse('{"id":"FIN-708","slug":"emerging-market","term":"Emerging Market","also_known_as":[],"difficulty":"Intermediate","definition":"An emerging market is a country whose economy is developing quickly and becoming more integrated with global markets, but which is not yet considered fully developed.","explanation":["Emerging markets typically have lower incomes per person than developed countries but faster economic growth, expanding middle classes and developing financial markets. Large examples have often included countries such as China, India, Brazil, Indonesia, Mexico and South Africa, although classifications change over time.","Index providers decide which countries count as emerging, developed or frontier markets, based on factors such as economic development, the size and liquidity of their stock markets, openness to foreign investors and the reliability of their market infrastructure.","Investors are attracted to emerging markets for their growth potential and for diversification. For example, a global investor might put a portion of their equity portfolio into an emerging markets fund to gain exposure to faster-growing economies.","Emerging markets also carry higher risks. These include political instability, weaker legal protections, less transparent companies, currency volatility, capital controls and greater sensitivity to global interest rates and commodity prices. Their stock markets have historically been more volatile than those of developed countries.","Many investors access emerging markets through diversified funds rather than individual shares, to spread these risks."],"note":"","total":1500,"prev":{"slug":"emergency-fund","term":"Emergency Fund"},"next":{"slug":"employee-stock-option-plan","term":"Employee Stock Option Plan (ESOP)"}}')}}]);